def ok(es, tr):
    return sorted(re.findall(r'\{\w+\}', es)) == sorted(re.findall(r'\{\w+\}', tr))


def main():
    web = {**COMMON, **WEB}
    for k, v in {**web, **EMAIL}.items():
        assert len(v) == 8, k
        for tr in v: assert ok(k, tr), (k, tr)
    out = {'exact': {es: dict(zip(LANGS, v)) for es, v in web.items()}, 'patterns': {}}
    (ROOT / 'scripts' / 'idiomas' / 'datos' / 'web_v50_55.json').write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding='utf-8')
    mails = {**COMMON, **EMAIL}
    for i, lang in enumerate(LANGS):
        f = ROOT / 'app' / 'emails' / f'{lang}.json'
        pack = json.loads(f.read_text(encoding='utf-8'))
        for es, v in mails.items():
            pack.setdefault(es, v[i])
        f.write_text(json.dumps(dict(sorted(pack.items())), ensure_ascii=False, indent=1), encoding='utf-8')
    # The app speaks es/en/fr: its list of texts (checked by the language tests) gets the app's new texts.
    app_new = {k: [web[k][0], web[k][1]] for k in ('Pago en persona al profesional', NOTICE, NO_POLICY, 'Formas de pago que acepta', 'Política del profesional',
                                                     'He leído el aviso: pago en persona al profesional', 'Efectivo', 'Bizum', 'Transferencia', 'Otra',
                                                     'Marca la casilla del aviso: este profesional cobra directamente, no a través de WORLDIVES.',
                                                     'El botón «Hablar por WhatsApp» aparece cuando el profesional acepta tu solicitud.',
                                                     'No pagas nada a través de WORLDIVES: acuerdas el pago con el profesional por WhatsApp cuando acepte.')}
    (ROOT / 'scripts' / 'idiomas' / 'datos' / 'app_v50_55.json').write_text(json.dumps(app_new, ensure_ascii=False, indent=1), encoding='utf-8')
    print('ok', len(web), 'web,', len(mails), 'correo,', len(app_new), 'app')


if __name__ == '__main__':
    sys.exit(main())
